package main

import (
	"regexp"
	"sort"
	"strings"
)

// Release-decoration vocabulary (design.md D-7): the bracket-segment rules,
// the whole-token release-tag tables, and the group-tag shape rule the series
// and episode grammars draw on. Role- and shape-keyed ONLY — no resource
// brand in any identifier, comment, or mask key — so this file can be
// extracted or replaced verbatim when the per-resource plugin projects land.

var (
	// bracketSegmentRe matches one [...] or (...) segment.
	bracketSegmentRe = regexp.MustCompile(`\[[^\]]*\]|\([^)]*\)`)
	// resolutionRe matches common video resolutions anywhere in a name —
	// derived from releaseTagTokens["resolution"], the vocabulary's single
	// source (design.md D-2).
	resolutionRe = buildResolutionRe()
	// crcHexRe matches a CRC-like 8-hex-digit token ([C48E56C8]).
	crcHexRe = regexp.MustCompile(`(?i)^[0-9a-f]{8}$`)
	// yearRe matches a bare release year.
	yearRe = regexp.MustCompile(`^(?:19|20)\d{2}$`)
	// pureNumberRe matches a 1-3 digit pure number ([01]).
	pureNumberRe = regexp.MustCompile(`^\d{1,3}$`)
	// subsRe matches a subtitle-combinator token (Multi5-Subs, SUBS).
	subsRe = regexp.MustCompile(`(?i)^(?:multi\d*-?)?subs$`)
	// allCapsRe matches an all-caps acronym of <= 5 letters ([ADN], [KTX]).
	allCapsRe = regexp.MustCompile(`^[A-Z0-9]{2,5}$`)
	// trailingGroupTagRe captures a trailing single word after a separator
	// (space, dot, underscore, or dash — " - FanGroup"); the word itself must
	// clear the group-tag shape rule before it is cut.
	trailingGroupTagRe = regexp.MustCompile(`[\s._\-]*([A-Za-z][A-Za-z0-9]*)[\s._\-]*$`)
)

// releaseTagTokens keys whole-token release tags by role. Matching is
// case-insensitive and delimiter-bounded; a tag with an embedded dash
// ("web-dl") also matches the run-together and dotted forms (WEBDL, WEB.DL).
// The language set is the shipped sidecar languageFolders set, replicated
// (sidecar.go:74 — no cross-import between package-main plugins).
var releaseTagTokens = map[string][]string{
	"source": {"web-dl", "webrip", "bluray", "bdrip", "bdremux", "hdtv", "hdrip", "dvdrip", "dvd"},
	"resolution": {
		"2160p", "1080p", "1080i", "720p", "480p", "360p", "4k",
	},
	"language": {
		"eng", "english", "rus", "russian", "jpn", "japanese",
		"ger", "german", "fre", "french", "fra", "spa", "spanish",
		"ita", "italian", "kor", "korean", "chi", "chinese", "zho",
		"ukr", "ukrainian", "pol", "polish",
	},
	"type":  {"ona", "ova", "oad"},
	"codec": {"x264", "x265", "h264", "h265", "avc", "hevc", "aac", "flac", "dts", "ac3", "opus"},
}

// releaseTagSet is the de-dashed lookup form of releaseTagTokens.
var releaseTagSet = func() map[string]bool {
	set := make(map[string]bool)
	for _, tags := range releaseTagTokens {
		for _, tag := range tags {
			set[tag] = true
			if strings.Contains(tag, "-") {
				set[strings.ReplaceAll(tag, "-", "")] = true
			}
		}
	}
	return set
}()

// stripBracketSegments applies the two-part bracket rule (design.md D-8): a
// bracket/paren segment at the name's start is group-tag position and strips
// regardless of its inner shape; a segment elsewhere strips only when its
// content matches a release mask (segmentIsReleaseDecoration); a non-leading
// segment matching no mask is PRESERVED — its title text keeps, e.g.
// "Title_(Shiro)".
func stripBracketSegments(name string) string {
	segs := bracketSegmentRe.FindAllStringSubmatchIndex(name, -1)
	if len(segs) == 0 {
		return name
	}
	var b strings.Builder
	last := 0
	for _, m := range segs {
		inner := strings.TrimSpace(name[m[0]+1 : m[1]-1])
		if strings.TrimSpace(name[:m[0]]) != "" && !segmentIsReleaseDecoration(inner) {
			continue // non-leading, no mask match — preserve the segment
		}
		b.WriteString(name[last:m[0]])
		b.WriteString(" ")
		last = m[1]
	}
	b.WriteString(name[last:])
	return b.String()
}

// segmentIsReleaseDecoration reports whether a bracket segment's inner text
// matches a release mask: a year, a pure 1-3 digit number, CRC-like hex, a
// subs/dub combinator, an all-caps acronym of <= 5 letters, a CamelCase group
// shape, or a rip-combinator segment CONTAINING any of those (design.md D-8).
func segmentIsReleaseDecoration(inner string) bool {
	if yearRe.MatchString(inner) || pureNumberRe.MatchString(inner) ||
		crcHexRe.MatchString(inner) || subsRe.MatchString(inner) ||
		allCapsRe.MatchString(inner) || isGroupTagShape(inner) {
		return true
	}
	tokens := strings.FieldsFunc(inner, func(r rune) bool {
		return r == ' ' || r == '.' || r == '_' || r == '-' || r == '+' || r == '/'
	})
	for _, tok := range tokens {
		if releaseTagSet[strings.ToLower(tok)] || subsRe.MatchString(tok) || isGroupTagShape(tok) {
			return true
		}
	}
	return false
}

// isGroupTagShape reports whether a single word is a release-group tag shape:
// >= 3 ASCII letters with mixed case AND an interior capital after a
// lowercase ("FanGroup"). An ordinary capitalized word ("Remastered",
// "Arc") has no interior capital and never matches (design.md D-5).
func isGroupTagShape(word string) bool {
	if len(word) < 3 {
		return false
	}
	hasLower, hasInteriorUpper := false, false
	for i := 0; i < len(word); i++ {
		c := word[i]
		switch {
		case c >= 'a' && c <= 'z':
			hasLower = true
		case c >= 'A' && c <= 'Z':
			if i > 0 {
				hasInteriorUpper = true
			}
		default:
			return false // a non-ASCII-letter byte: not a single CamelCase word
		}
	}
	return hasLower && hasInteriorUpper
}

// releaseTagPatterns compiles one flexible-separator pattern per table token:
// a tag's embedded dash also matches a dot, underscore, space, or the
// run-together form ("WEB-DL" == "WEBDL" == "WEB.DL").
var releaseTagPatterns = buildReleaseTagPatterns()

func buildReleaseTagPatterns() []*regexp.Regexp {
	seen := make(map[string]bool, len(releaseTagSet))
	pats := make([]*regexp.Regexp, 0, len(releaseTagSet))
	for _, tags := range releaseTagTokens {
		for _, tag := range tags {
			if seen[tag] {
				continue
			}
			seen[tag] = true
			flex := strings.ReplaceAll(regexp.QuoteMeta(tag), "-", `[._\- ]?`)
			pats = append(pats, regexp.MustCompile(
				`(?i)(?:^|[\s._\-\[(])`+flex+`(?:$|[\s._\-\])])`))
		}
	}
	return pats
}

// buildResolutionRe compiles the resolution alternation over the token
// table's values, sorted length-descending so a longer token is never
// shadowed by a shorter prefix inside the alternation.
func buildResolutionRe() *regexp.Regexp {
	tokens := append([]string(nil), releaseTagTokens["resolution"]...)
	sort.Slice(tokens, func(i, j int) bool { return len(tokens[i]) > len(tokens[j]) })
	parts := make([]string, len(tokens))
	for i, tok := range tokens {
		parts[i] = regexp.QuoteMeta(tok)
	}
	return regexp.MustCompile(`(?i)(?:` + strings.Join(parts, "|") + `)`)
}

// stripReleaseTagTokens cuts whole-token release tags of every role from a
// name, case-insensitive, delimiter-bounded ("From.S02.WEBDL.720p.Rus.Eng"
// keeps only "From").
func stripReleaseTagTokens(name string) string {
	for _, re := range releaseTagPatterns {
		name = re.ReplaceAllString(name, " ")
	}
	return name
}

// cutTrailingGroupTag removes a trailing single-word release-group tag after
// a separator ("- FanGroup") when the word clears the group-tag shape
// rule; a multi-word segment is preserved whole (design.md D-1 step 6).
func cutTrailingGroupTag(name string) string {
	m := trailingGroupTagRe.FindStringSubmatchIndex(name)
	if m == nil || !isGroupTagShape(name[m[2]:m[3]]) {
		return name
	}
	return name[:m[0]]
}
